	Let $a: \ag{R}_+ \to \ag{C}$ be a continuous function. It is \emph{regularizable} if
\begin{itemize}
	\item[(1)] for any $N \gg 1$ as $t \to \infty$
	$$ a(t) = f(t)+O(t^{-N}), \quad f(t)=\sum_{i=1}^l \frac{c_i}{n_i!} t^{\frac{1}{2}+\alpha_i} \log^{n_i}t, $$
where $c_i, \alpha_i \in \ag{C}, n_i \in \ag{N}$;
	\item[(2)] for some $\alpha \in \ag{R}$ as $t \to 0^+$
	$$ a(t) = O(t^{\alpha}). $$
 \end{itemize}
 	In this case, we write for $T > 0$
 	$$ h_T(s) = \sum_{i=1}^l \frac{c_i}{n_i!} \frac{\partial^{n_i}}{\partial s^{n_i}} \left( \frac{T^{s+\alpha_i}}{s+\alpha_i} \right) = \sum_{i=1}^l c_i \sum_{m=0}^{n_i} \frac{(-1)^{n_i-m}}{m!} \frac{T^{s+\alpha_i} \log^m T}{(s+\alpha_i)^{n_i-m+1}}. $$
 \label{RegFuncRDef}

	If not, the condition implies that
\begin{align*}
	\int_1^T f(t) \frac{dt}{t^2} &= \sum_{\alpha_j \neq \frac{1}{2}} c_j \sum_{m=0}^{n_j} \frac{(-1)^{n_j-m}}{(\alpha_j - \frac{1}{2})^{n_j-m+1}} T^{\alpha_j-\frac{1}{2}} (\log T)^m - \sum_{\alpha_j \neq \frac{1}{2}} c_j \frac{(-1)^{n_j}}{(\alpha_j-\frac{1}{2})^{n_j+1}} \\
	&\quad + \sum_{\alpha_j=\frac{1}{2}} \frac{c_j}{n_j!} \frac{(\log T)^{n_j+1}}{n_j+1}
\end{align*}
is bounded as $T \to +\infty$. Let $\sigma = \max_j \Re \alpha_j$. We distinguish two cases.

\noindent (1) $\sigma=1/2$. Let $l=\max \{ n_j: \Re \alpha_j = 1/2, \alpha_j \neq 1/2 \} \cup \{ n_j+1: \alpha_j=1/2 \}$. We divide both sides of the equation by $(\log T)^l$ and let $T \to +\infty$ to get
\begin{equation}
	\lim_{T \to \infty} \sum c_j T^{i\tau_j} = 0
\label{AbsEq}
\end{equation}
where $\Im \alpha_j = \tau_j$ for $j$ such that either $\Re \alpha_j = 1/2, \alpha_j \neq 1/2, n_j=l$ or $\alpha_j=1/2, n_j+1=l$. In particular $\tau_j$ are mutually distinct.

\noindent (2) $\sigma > 1/2$. Let $l=\max \{ n_j: \Re \alpha_j = \sigma \}$. We divide both sides of the equation by $T^{\sigma-1/2} (\log T)^l$ and let $T \to +\infty$ to get an equation of the same form as (\ref{AbsEq}).

\noindent We conclude because (\ref{AbsEq}) contradicts the following Corollary \ref{ErgodicLemma}.

\begin{align*}
	\int_1^T f(t) \frac{dt}{t^2} &= \sum_{\alpha_j \neq \frac{1}{2}} c_j \sum_{m=0}^{n_j} \frac{(-1)^{n_j-m}}{(\alpha_j - \frac{1}{2})^{n_j-m+1}} T^{\alpha_j-\frac{1}{2}} (\log T)^m - \sum_{\alpha_j \neq \frac{1}{2}} c_j \frac{(-1)^{n_j}}{(\alpha_j-\frac{1}{2})^{n_j+1}} \\
	&\quad + \sum_{\alpha_j=\frac{1}{2}} \frac{c_j}{n_j!} \frac{(\log T)^{n_j+1}}{n_j+1}
\end{align*}

\begin{equation}
	\lim_{T \to \infty} \sum c_j T^{i\tau_j} = 0
\label{AbsEq}
\end{equation}

	Let $\varphi: {\rm GL}_2(\mathbf{F})\gp{Z}(\ag{A}) \backslash {\rm GL}_2(\ag{A}) \to \ag{C}$ be a continuous function. It is \emph{slowly increasing} if for some $c \in \ag{R}$ and $g$ lying in some Siegel domain we have
	$$ \norm[\varphi(g)] \ll {\rm Ht}(g)^c, {\rm Ht}(g) \to \infty. $$
\label{SlowIncDef}

	If $\varphi$ is slowly increasing as in Definition \ref{SlowIncDef}, then we have
	$$ \norm[\varphi(g)] \ll {\rm Ht}(g)^{\min(0,-c)}, {\rm Ht}(g) \to 0. $$
\label{SIncBdAt0}

\noindent The following function together with its Taylor expansion plays an important role:
\begin{equation}
	\lambda_{\mathbf{F}}(s) := \frac{\Lambda_{\mathbf{F}}(-2s)}{\Lambda_{\mathbf{F}}(2+2s)} = \frac{\lambda_{\mathbf{F}}^{-1}(0)}{s} + \sum_{n=0}^{\infty} \frac{s^n}{n!} \lambda_{\mathbf{F}}^{(n)}(0).
\label{lambdaFDef}
\end{equation}

\begin{equation}
	\lambda_{\mathbf{F}}(s) := \frac{\Lambda_{\mathbf{F}}(-2s)}{\Lambda_{\mathbf{F}}(2+2s)} = \frac{\lambda_{\mathbf{F}}^{-1}(0)}{s} + \sum_{n=0}^{\infty} \frac{s^n}{n!} \lambda_{\mathbf{F}}^{(n)}(0).
\label{lambdaFDef}
\end{equation}

\begin{align*}
	&\quad R^*(s,\varphi) + \Lambda_{\mathbf{F}}(1+2s) h_T(s) + \Lambda_{\mathbf{F}}(1-2s) h_T(-s) \\
	&= \int_{[{\rm PGL}_2]} \varphi(g) \Lambda^T {\rm E}^*(s,f_0)(g) dg + \\
	&\quad \Lambda_{\mathbf{F}}(1+2s) \int_T^{\infty} (a(t,\varphi)-f(t)) t^{s-\frac{1}{2}} \frac{dt}{t} + \Lambda_{\mathbf{F}}(1-2s) \int_T^{\infty} (a(t,\varphi)-f(t)) t^{-s-\frac{1}{2}} \frac{dt}{t}.
\end{align*}

\begin{align*}
	\int_0^T a(t,\varphi) t^{s-\frac{1}{2}} \frac{dt}{t} &= R(s,\varphi) - \int_T^{\infty} (a(t,\varphi)-f(t)) t^{s-\frac{1}{2}} \frac{dt}{t} + \sum_{i=1}^l \frac{c_i}{n_i!} \int_0^T t^{s+\alpha_i} \log^{n_i} t \frac{dt}{t} \\
	&= R(s,\varphi) - \int_T^{\infty} (a(t,\varphi)-f(t)) t^{s-\frac{1}{2}} \frac{dt}{t} + h_T(s).
\end{align*}

\begin{align*}
	&\quad {\rm Res}_{s=\frac{1}{2}} R(s,\varphi) + {\rm Res}_{s=\frac{1}{2}} h_T(s) + \lambda_{\mathbf{F}}^{(-1)}(0) h_T(-\frac{1}{2}) \\
	&= \lambda_{\mathbf{F}}^{(-1)}(0) \int_{\mathcal{D}_T} \varphi(g)dg + {\rm Res}_{s=\frac{1}{2}} \int_{\mathcal{D}-\mathcal{D}_T} \varphi(g) \left( {\rm E}(s,f_0)(g) - {\rm E}(s,f_0)_N(g) \right) dg \\
	&\quad + \lambda_{\mathbf{F}}^{(-1)}(0) \int_T^{\infty} (a(t,\varphi)-f(t)) \frac{dt}{t^2},
\end{align*}

	By Proposition \ref{GlobRDEisWhi}, \ref{GlobRDEisCst} and the definition of cusp forms, $\mathcal{A}^{{\rm fr}}({\rm GL}_2,\omega)$ contains:
\begin{itemize}
	\item $\chi(\det g)$ for quasi-characters $\chi$ such that $\chi^2=\omega$;
	\item smooth cusp forms, i.e., $\mathcal{A}_{{\rm cusp}}^{\infty}({\rm GL}_2,\omega)$;
	\item $\frac{\partial^n}{\partial s^n}{\rm E}(s,f)$ for some $n \in \ag{N}$ and smooth $f \in {\rm Ind}_{\gp{B}(\ag{A})}^{{\rm GL}_2(\ag{A})}(\xi, \omega\xi^{-1})$ with $\Re s \geq 0$ and $s \neq -i\mu/2, 1/2-i\mu/2$ for $\mu=\mu(\omega^{-1}\xi^2)$ if $\omega\xi^{-2}$ is trivial on $\ag{A}^{(1)}$;
	\item $\frac{\partial^n}{\partial s^n} \mid_{s=-i\frac{\mu}{2}} (s+i\frac{\mu}{2}){\rm E}^*(s,f)$ for some $n \in \ag{N}$ and smooth $f$, $\mu$ the same as above;
	\item $\frac{\partial^n}{\partial s^n}{\rm E}^{{\rm reg}}(\frac{1-i\mu}{2},f)$ for some $n \in \ag{N}$ and $f,\mu$ the same as above;
	\item $\varphi=\Pi_{j=1}^l \varphi_j$ where $\varphi_j \in \mathcal{A}^{{\rm fr}}({\rm GL}_2,\omega_j)$ with $\omega = \Pi_j \omega_j$.
\end{itemize}
	In the last case, we have $ \varphi_{\gp{N}}^* = \Pi_j \varphi_{j,\gp{N}}^* $. Note that we have excluded ${\rm E}(s,f)$ for $\Re s < 0$. But they are actually present since they are related to the case $\Re s > 0$ by functional equation.

	$\mathcal{A}^{{\rm fr}}({\rm GL}_2,\omega)$ is stable under the right translation by ${\rm GL}_2(\ag{A})$. Moreover, for any $\varphi \in \mathcal{A}^{{\rm fr}}({\rm GL}_2,\omega)$ and any $g \in {\rm GL}_2(\ag{A})$, their sets of exponents are the same:
	$$ \mathcal{E}{\rm x}(g.\varphi) = \mathcal{E}{\rm x}(\varphi). $$
\label{FregStab}

\begin{align*}
	\sideset{}{_{k=0}^n} \sum \frac{\partial^k}{\partial s^k} \mid_{s=s_0} \mathcal{M}_s f_{k,s} &= \sideset{}{_{k=0}^n} \sum \sideset{}{_{\vec{k}}} \sum \binom{n}{k} a_{\vec{k}}^{(n-k)}(s_0,g) \frac{\partial^k}{\partial s^k} \mid_{s=s_0} (\mu_{\vec{k}}(s) \tilde{e}_{\vec{k},-s}) \\
	&= \sideset{}{_{\vec{k}}} \sum \frac{\partial^n}{\partial s^n} \mid_{s=s_0} (a_{\vec{k}}(s,g) \mu_{\vec{k}}(s) \tilde{e}_{\vec{k},-s}) = \frac{\partial^n}{\partial s^n} \mid_{s=s_0} \mathcal{M}_s f_s,
\end{align*}

	Let $\varphi \in \mathcal{A}^{{\rm fr}}({\rm GL}_2,\omega)$.
\begin{itemize}
	\item[(1)] We can always find (not unique) $\mathcal{E}(\varphi) \in \mathcal{E}({\rm GL}_2,\omega)$ such that $\varphi - \mathcal{E}(\varphi) \in {\rm L}^1({\rm GL}_2, \omega)$.
	\item[(2)] If for any $\chi \in \mathcal{E}{\rm x}(\varphi)$, we have $\Re \chi \neq 1/2$, then there is a unique function $\mathcal{E}(\varphi) \in \mathcal{E}({\rm GL}_2,\omega)$ such that $\varphi - \mathcal{E}(\varphi) \in {\rm L}^2({\rm GL}_2, \omega)$. Moreover, for any $X$ in the universal enveloping algebra of ${\rm GL}_2(\ag{A}_{\infty})$, we have $X.\varphi - X.\mathcal{E}(\varphi) \in {\rm L}^2({\rm GL}_2, \omega)$, i.e., $\mathcal{E}(X.\varphi) = X.\mathcal{E}(\varphi)$.
\end{itemize}
\label{ResSp}

	By Lemma \ref{IntExpBd} and Proposition \ref{GlobRDEisWhi}, it is not difficult to see that $\mathcal{E}({\rm GL}_2,\omega) \cap {\rm L}^2({\rm GL}_2(\mathbf{F}) \backslash {\rm GL}_2(\ag{A}), \omega) = \{0\}$, which implies the uniqueness of $\mathcal{E}(\varphi)$ in (2). For the existence, we find $\chi_i, \alpha_i, n_i, f_i$ as in Definition \ref{FinRegFuncDef}. Then we take, writing $\mu_i = \mu(\omega^{-1}\chi_i^2)$,
\begin{equation}
	\mathcal{E}(\varphi) = \sum_{\substack{\Re \alpha_j > 0 \\ \alpha_j \neq \frac{1}{2}+i\mu_j}} \frac{\partial^{n_j}}{\partial s^{n_j}}{\rm E}(\alpha_j,\omega,\omega^{-1}\chi_j;f_j) + \sum_{\substack{\Re \alpha_j > 0 \\ \alpha_j = \frac{1}{2}+i\mu_j}} \frac{\partial^{n_j}}{\partial s^{n_j}}{\rm E}^{{\rm reg}}(\alpha_j,\omega,\omega^{-1}\chi_j;f_j).
\label{ReisDef}
\end{equation}
	Thus for any $\chi \in \mathcal{E}{\rm x}(\varphi-\mathcal{E}(\varphi))$, we have $\Re \chi \leq 1/2$ resp. $\Re \chi < 1/2$ under the condition in (2). Hence $\varphi-\mathcal{E}(\varphi) \in {\rm L}^1({\rm GL}_2, \omega)$ resp. ${\rm L}^2({\rm GL}_2, \omega)$. For the ``moreover'' part, it suffices to see that the differential operator $X$ does not increase the real part of elements in $\mathcal{E}{\rm x}(\varphi)$, which is essentially due to the following calculation:
	$$ y \frac{d}{dy} (y^{\sigma} \log^k y) = y^{\sigma} \log^k y + k y^{\sigma} \log^{k-1}y, \forall y>0, \sigma \in \ag{C}, k \in \ag{N}. $$

\begin{equation}
	\mathcal{E}(\varphi) = \sum_{\substack{\Re \alpha_j > 0 \\ \alpha_j \neq \frac{1}{2}+i\mu_j}} \frac{\partial^{n_j}}{\partial s^{n_j}}{\rm E}(\alpha_j,\omega,\omega^{-1}\chi_j;f_j) + \sum_{\substack{\Re \alpha_j > 0 \\ \alpha_j = \frac{1}{2}+i\mu_j}} \frac{\partial^{n_j}}{\partial s^{n_j}}{\rm E}^{{\rm reg}}(\alpha_j,\omega,\omega^{-1}\chi_j;f_j).
\label{ReisDef}
\end{equation}

\begin{itemize}


	\item[(1)] For any $\mathcal{E} \in \mathcal{E}({\rm GL}_2,1)$, we have
	$$ \int_{[{\rm PGL}_2]}^{{\rm reg}} \mathcal{E}(g) dg = 0. $$
	If moreover $\mathcal{E} \in \mathcal{E}^+({\rm GL}_2,1)$, then for any $g_0 \in {\rm GL}_2(\ag{A})$, we have
	$$ \int_{[{\rm PGL}_2]}^{{\rm reg}} g_0.\mathcal{E}(g) dg = 0. $$
	\item[(2)] Let $\varphi \in \mathcal{A}^{{\rm fr}}({\rm GL}_2,1)$. For any $\mathcal{E} \in \mathcal{E}({\rm GL}_2,1)$ such that $\varphi - \mathcal{E} \in {\rm L}^1([{\rm PGL}_2])$ we have
	$$ \int_{[{\rm PGL}_2]}^{{\rm reg}} \varphi(g) dg = \int_{[{\rm PGL}_2]} (\varphi-\mathcal{E})(g) dg. $$
	In particular, $\int_{[{\rm PGL}_2]}^{{\rm reg}}$ is always $\gp{K}$-invariant. It is ${\rm GL}_2(\ag{A})$-invariant on the subspace of $\varphi \in \mathcal{A}^{{\rm fr}}({\rm GL}_2,1)$ such that $\mathcal{E}{\rm x}(\varphi)$ does not contain $\norm_{\ag{A}}$.
\end{itemize}
\label{RegGInv}

\begin{align*}
	a(t,\mathcal{E}) &= \zeta_{\mathbf{F}}^*(1) \int_{\gp{K}} f(k)dk \cdot \\
	&\quad \left\{ t \log^n t + \frac{\partial^n}{\partial s^n} \mid_{s=\frac{1}{2}-i\mu(\chi)} \left( (t^{\frac{1}{2}-s-i\mu(\chi)}-1) \frac{\Lambda_{\mathbf{F}}(1-2s-2i\mu(\chi))}{\Lambda_{\mathbf{F}}(1+2s+2i\mu(\chi))} \right) \right\} \\
	&= \zeta_{\mathbf{F}}^*(1) \int_{\gp{K}} f(k)dk \cdot \\
	&\quad \left\{ t \log^n t + \sum_{l=0}^n \binom{n}{l} \frac{(-1)^l}{l+1} \cdot \log^{l+1}t \cdot \frac{d^{n-l}}{d s^{n-l}} \mid_{s=0} \left( \frac{s\Lambda_{\mathbf{F}}(2s)}{\Lambda_{\mathbf{F}}(2-2s)} \right) \right\},
\end{align*}

	Let $\xi_j,\xi_j'$ be (unitary) Hecke characters with $\xi_1\xi_1' \xi_2 \xi_2' = 1$ and write $\pi_j = \pi(\xi_j,\xi_j')$, $j=1,2$. For $f_j \in \pi_j$, we shall write ${\rm E}^{\sharp}$ for ${\rm E}$ or ${\rm E}^{{\rm reg}}$, whichever is regular at $s=1/2$. If $\pi_1 \not \simeq \widetilde{\pi_2}$, then for any $n_1, n_2 \in \ag{N}$, we have
	$$ \int_{[{\rm PGL}_2]}^{{\rm reg}} {\rm E}^{(n_1)}(0,f_1) {\rm E}^{(n_2)}(0,f_2) = 0, \quad \int_{[{\rm PGL}_2]}^{{\rm reg}} {\rm E}^{\sharp,(n_1)}(1/2,f_1) {\rm E}^{\sharp,(n_2)}(1/2,f_2) = 0. $$
\label{SimpleProd}

In general, if $\varphi \in \mathcal{A}^{{\rm fr}}({\rm PGL}_2), \mathcal{E} \in \mathcal{E}({\rm PGL}_2)$ are given, so that $\varphi - \mathcal{E} \in {\rm L}^1([{\rm PGL}_2])$, and if we can find continuous families $\varphi_s \in \mathcal{A}^{{\rm fr}}({\rm PGL}_2), \mathcal{E}_s \in \mathcal{E}({\rm PGL}_2)$ which coincide with $\varphi, \mathcal{E}$ at $s=0$, then we have
\begin{equation}
	\int_{[{\rm PGL}_2]}^{{\rm reg}} \varphi = \int_{[{\rm PGL}_2]} \varphi - \mathcal{E} = \lim_{s \to 0} \int_{[{\rm PGL}_2]} \varphi_s - \mathcal{E}_s = \lim_{s \to 0} \left( \int_{[{\rm PGL}_2]}^{{\rm reg}} \varphi_s - \int_{[{\rm PGL}_2]}^{{\rm reg}} \mathcal{E}_s \right).
\label{DeformTec}
\end{equation}

\begin{equation}
	\int_{[{\rm PGL}_2]}^{{\rm reg}} \varphi = \int_{[{\rm PGL}_2]} \varphi - \mathcal{E} = \lim_{s \to 0} \int_{[{\rm PGL}_2]} \varphi_s - \mathcal{E}_s = \lim_{s \to 0} \left( \int_{[{\rm PGL}_2]}^{{\rm reg}} \varphi_s - \int_{[{\rm PGL}_2]}^{{\rm reg}} \mathcal{E}_s \right).
\label{DeformTec}
\end{equation}

	Let $f_1,f_2 \in {\rm Res}_{\gp{K}}^{{\rm GL}_2(\ag{A})} \pi(1,1)$. For $0 \neq s \in \ag{C}$ small, we have
	$$ \int_{[{\rm PGL}_2]}^{{\rm reg}} {\rm E}(s,f_1) {\rm E}^{(1)}(0,f_2) = 0. $$
\label{SimpleProdU}

\begin{align*}
	\mathcal{E}^{{\rm reg}}(s) &:= s^{-1} \left\{ 2 {\rm E}^{{\rm reg},(1)}(1/2+s, f_1f_2) + 2 {\rm E}^{{\rm reg},(1)}(1/2-s, \mathcal{M}_s f_1f_2) \right. \\
	 &\left. + {\rm E}^{{\rm reg}}(1/2+s, f_1 \mathcal{M}_0^{(1)}f_2) + {\rm E}^{{\rm reg}}(1/2-s, \mathcal{M}_s f_1 \mathcal{M}_0^{(1)}f_2) \right\}
\end{align*}

Applying Lemma \ref{SimpleProdU}, \ref{SimpleProdSing} with $n=0, 1$ together with (\ref{DeformTec}), we get
\begin{align*}
	\int_{[{\rm PGL}_2]}^{{\rm reg}} {\rm E}^{(1)}(0,f_1) {\rm E}^{(1)}(0,f_2) &= \lim_{s \to 0} \int_{[{\rm PGL}_2]} s^{-1} {\rm E}(s,f_1) {\rm E}^{(1)}(0,f_2) - \mathcal{E}^{{\rm reg}}(s) \\
	&= \frac{1}{s} \cdot \left\{ 2 \frac{\lambda_{\mathbf{F}}^{(1)}(s)}{\lambda_{\mathbf{F}}^{(-1)}(0)} {\rm P}_{\gp{K}}(f_1f_2) + 2  \frac{\lambda_{\mathbf{F}}^{(1)}(-s)}{\lambda_{\mathbf{F}}^{(-1)}(0)} {\rm P}_{\gp{K}}(\mathcal{M}_s f_1f_2) \right. \\
	&\left. + \frac{\lambda_{\mathbf{F}}(s)}{\lambda_{\mathbf{F}}^{(-1)}(0)} {\rm P}_{\gp{K}}(f_1 \mathcal{M}_0^{(1)}f_2) + \frac{\lambda_{\mathbf{F}}(-s)}{\lambda_{\mathbf{F}}^{(-1)}(0)} {\rm P}_{\gp{K}}(\mathcal{M}_s f_1 \mathcal{M}_0^{(1)}f_2) \right\}.
\end{align*}

\begin{align*}
	\int_{[{\rm PGL}_2]}^{{\rm reg}} {\rm E}^{(1)}(0,f_1) {\rm E}^{(1)}(0,f_2) &= \lim_{s \to 0} \int_{[{\rm PGL}_2]} s^{-1} {\rm E}(s,f_1) {\rm E}^{(1)}(0,f_2) - \mathcal{E}^{{\rm reg}}(s) \\
	&= \frac{1}{s} \cdot \left\{ 2 \frac{\lambda_{\mathbf{F}}^{(1)}(s)}{\lambda_{\mathbf{F}}^{(-1)}(0)} {\rm P}_{\gp{K}}(f_1f_2) + 2  \frac{\lambda_{\mathbf{F}}^{(1)}(-s)}{\lambda_{\mathbf{F}}^{(-1)}(0)} {\rm P}_{\gp{K}}(\mathcal{M}_s f_1f_2) \right. \\
	&\left. + \frac{\lambda_{\mathbf{F}}(s)}{\lambda_{\mathbf{F}}^{(-1)}(0)} {\rm P}_{\gp{K}}(f_1 \mathcal{M}_0^{(1)}f_2) + \frac{\lambda_{\mathbf{F}}(-s)}{\lambda_{\mathbf{F}}^{(-1)}(0)} {\rm P}_{\gp{K}}(\mathcal{M}_s f_1 \mathcal{M}_0^{(1)}f_2) \right\}.
\end{align*}


	If $\pi(\xi_1,\xi_2)$ is spherical, we also write 
	The regularized integral of the product of two unitary Eisenstein series is computed as:
\begin{itemize}
	\item[(1)] If $\pi_1 = \pi(\xi_1,\xi_2), \pi_2 = \pi(\xi_1^{-1}, \xi_2^{-1})$ resp. $\pi_2 = \pi(\xi_2^{-1}, \xi_1^{-1})$ and $\xi_1 \neq \xi_2$, then
	$$ \int_{[{\rm PGL}_2]}^{{\rm reg}} {\rm E}(0,f_1) {\rm E}(0,f_2) = \frac{2\lambda_{\mathbf{F}}^{(0)}(0)}{\lambda_{\mathbf{F}}^{(-1)}(0)} {\rm P}_{\gp{K}}(f_1f_2) - {\rm P}_{\gp{K}}(\mathcal{M}_0^{(1)}f_1 \cdot \mathcal{M}_0 f_2), \quad \text{resp.} $$
	$$ \frac{\lambda_{\mathbf{F}}^{(0)}(0)}{\lambda_{\mathbf{F}}^{(-1)}(0)} ({\rm P}_{\gp{K}}(f_1 \mathcal{M}_0 f_2) + {\rm P}_{\gp{K}}(f_2 \mathcal{M}_0 f_1)) - {\rm P}_{\gp{K}}(\mathcal{M}_0^{(1)}f_1 \cdot f_2). $$
	\item[(2)] If $\pi_1 = \pi(\xi,\xi), \pi_2 = \pi(\xi^{-1},\xi^{-1})$, then
\begin{align*}
	&\quad \int_{[{\rm PGL}_2]}^{{\rm reg}} {\rm E}^{(1)}(0,f_1) {\rm E}^{(1)}(0,f_2) = \frac{4\lambda_{\mathbf{F}}^{(2)}(0)}{\lambda_{\mathbf{F}}^{-1}(0)} {\rm P}_{\gp{K}}(f_1f_2) + \frac{4\lambda_{\mathbf{F}}^{(2)}(0)}{\lambda_{\mathbf{F}}^{-1}(0)} {\rm P}_{\gp{K}}(f_1 \cdot \mathcal{M}_0^{(1)} f_2) \\
	&\quad + \frac{\lambda_{\mathbf{F}}^{(0)}(0)}{\lambda_{\mathbf{F}}^{-1}(0)} {\rm P}_{\gp{K}}(\mathcal{M}_0^{(1)}f_1 \cdot \mathcal{M}_0^{(1)}f_2) - \frac{1}{3} {\rm P}_{\gp{K}}(\mathcal{M}_0^{(3)}f_1 \cdot f_2) - {\rm P}_{\gp{K}}(\mathcal{M}_0^{(2)}f_1 \cdot \mathcal{M}_0^{(1)}f_2).
\end{align*}
\end{itemize}
\label{RIPEisUnitary}

\begin{align*}
	&\quad \int_{[{\rm PGL}_2]}^{{\rm reg}} {\rm E}^{(1)}(0,f_1) {\rm E}^{(1)}(0,f_2) = \frac{4\lambda_{\mathbf{F}}^{(2)}(0)}{\lambda_{\mathbf{F}}^{-1}(0)} {\rm P}_{\gp{K}}(f_1f_2) + \frac{4\lambda_{\mathbf{F}}^{(2)}(0)}{\lambda_{\mathbf{F}}^{-1}(0)} {\rm P}_{\gp{K}}(f_1 \cdot \mathcal{M}_0^{(1)} f_2) \\
	&\quad + \frac{\lambda_{\mathbf{F}}^{(0)}(0)}{\lambda_{\mathbf{F}}^{-1}(0)} {\rm P}_{\gp{K}}(\mathcal{M}_0^{(1)}f_1 \cdot \mathcal{M}_0^{(1)}f_2) - \frac{1}{3} {\rm P}_{\gp{K}}(\mathcal{M}_0^{(3)}f_1 \cdot f_2) - {\rm P}_{\gp{K}}(\mathcal{M}_0^{(2)}f_1 \cdot \mathcal{M}_0^{(1)}f_2).
\end{align*}

\begin{align*}
	{\rm E}_{\gp{N}}^{{\rm reg},(n)}(\frac{1}{2},f) &= f_{1/2}^{(n)} + \sum_{k=0}^n \binom{n}{k} (-1)^k (\widetilde{\mathcal{M}}_{1/2}^{(n-k)} f)_{-1/2}^{(k)} \\
	&+ {\rm P}_{\gp{K}}(f) \cdot \left\{ \frac{(-1)^{n+1} \lambda_{\mathbf{F}}^{-1)}(0)}{n+1} e_{-1/2}^{(n+1)} + \sum_{k=1}^n \binom{n}{k} (-1)^k \lambda_{\mathbf{F}}^{(n-k)}(0) e_{-1/2}^k \right\},
\end{align*}

\begin{align*}
	&\quad \int_{[{\rm PGL}_2]}^{{\rm reg}} {\rm E}^{{\rm reg}}(\frac{1}{2},f_1) {\rm E}^{{\rm reg},(n_2)}(\frac{1}{2},f_2) = \lim_{s \to 0} \int_{[{\rm PGL}_2]} {\rm E}^{{\rm reg}}(\frac{1}{2}+s,f_1) {\rm E}^{{\rm reg},(n_2)}(\frac{1}{2},f_2) - \mathcal{E}^{{\rm reg}}(s) \\
	&= \lim_{s \to 0} \sum_{k=0}^{n_2} \binom{n_2}{k} \frac{(-1)^k}{\lambda_{\mathbf{F}}^{(-1)}(0)} \lambda_{\mathbf{F}}^{(k)}(s) {\rm P}_{\gp{K}}(f_1 \widetilde{\mathcal{M}}_{1/2}^{(n_2-k)} f_2) + \frac{\lambda_{\mathbf{F}}^{(n_2)}(-s)}{\lambda_{\mathbf{F}}^{(-1)}(0)} {\rm P}_{\gp{K}}(f_2 \widetilde{\mathcal{M}}_{1/2+s}f_1) \\
	&\quad + {\rm P}_{\gp{K}}(f_1) {\rm P}_{\gp{K}}(f_2) \cdot \left\{ \frac{(-1)^{n_2+1} \lambda_{\mathbf{F}}^{(n_2+1)}(s)}{n_2+1} + \sum_{k=1}^{n_2} \binom{n_2}{k} (-1)^k \frac{\lambda_{\mathbf{F}}^{(n_2-k)}(0) \lambda_{\mathbf{F}}^{(k)}(s)}{\lambda_{\mathbf{F}}^{(-1)}(0)} + \lambda_{\mathbf{F}}(s) \lambda_{\mathbf{F}}^{(n_2)}(-s) \right\}.
